{#- ------ Ingest Template Macro Start ----- -#} 
{# IMPORTANT: this Ingest Macro can only be used for multiple value/array elements.
You should never use this Ingest Macro for the Archipelago required "type" or "label" JSON keys. #}
{%- macro ingest(destination_key, source_datum) -%} 
  {%- if source_datum and source_datum|length > 0 -%} 
   ,"{{destination_key}}": {{ source_datum|json_encode|raw }}
  {%- endif -%} 
{%- endmacro ingest -%} 
{# Allison's Value/Label + Source/Type/URI Ingest Macro - uses some logic from Diego #}
 {%- macro ingest_pair(destination_key, source_datum_value, source_datum_source, value_key, source_key) -%}
  {% set value_key = value_key|default("value") %}
  {% set source_key = source_key|default("source") %}
 
 {% if source_datum_value is iterable and not empty %}
  {% set values = [] %}
  {% for index,value in source_datum_value %}
      {% set value_by_source = { (value_key): value, (source_key): source_datum_source[index]|default("")} %}
      {% set values = values|merge([value_by_source]) %}
  {% endfor %}
  {% if values is not empty %}
,"{{destination_key}}": {{ values|json_encode|raw }}
  {% endif %}
{% endif %}
{%- endmacro ingest_pair -%}
{#subproperty_mappings is an object in the form of:
{'original_subproperty':'destination_subproperty'}
add_comma_before = false|true|null, the later for no comma at all #}
{%- macro ingest_with_mapped_properties(destination_key, source_datum, subproperty_mappings, add_comma_before) -%} 
  {% set values = [] %}
  {% set add_comma_before = add_comma_before|default(false) %}
  {% if source_datum is iterable %}
    {% set value_by_source_indexed = {} %}
    {% for index,value in source_datum %}
    	 {% if subproperty_mappings[index] is defined %}
          {# means source_datum is an object #}
           {% set value_by_source_indexed = value_by_source_indexed|merge({(subproperty_mappings[index]): (value)}) %}
         {% else %}
          {# means source_datum is an numerically indexed array and value might be an object #}
           {% if value is iterable %}
               {% set value_by_source = {} %}
               {% for property, subvalue in value %}
                 {% if subproperty_mappings[property] is defined %}
                   {% set value_by_source = value_by_source|merge({(subproperty_mappings[property]): (subvalue)}) %}
                 {% endif %}
               {% endfor %}
               {% if value_by_source is not empty %}
                  {% set values = values|merge([value_by_source]) %}
               {% endif %}
           {% endif %}
         {% endif %}
    {% endfor %}
     {% if value_by_source_indexed is not empty %}
          {% set values = values|merge([value_by_source_indexed]) %}
     {% endif %}
  {% endif %}
{%- if values|length > 0 -%} 
{{- add_comma_before == true ? ',' : '' -}}"{{-destination_key-}}": {{- values|json_encode|raw -}}{{- add_comma_before == false ? ',' : '' -}}
{%- endif -%}
{%- endmacro ingest_with_mapped_properties -%}

{# IMPORTANT: this Ingest Macro returns a JSON encoded array, which then needs to be sbf_json_decoded. #}
{% macro process_date_edtf(datestring) -%}
{% set valid_dates = [] %}
{%- if datestring is not empty and datestring is instanceof("scalar") %}
{% set datestring = datestring|preg_replace('|[^0-9\\-u/\/]+|', '$1') %}
{% set datestring = datestring|replace({'u': 'X'}) %}
{% set datestring = datestring|replace({'--': '/'}) %}
{% set dates = datestring|split(" ") %}
{% for date in dates %}
{# New, exclude any date where the year is unknown #}
  {% if date|edtf_2_iso_date is not empty and ("XXXX" not in date) %}
    {% set valid_dates = valid_dates|merge([date]) %}
  {% endif %}
{% endfor %}
{%- endif -%}
{{ valid_dates|json_encode|raw }}
{%- endmacro process_date_edtf -%} 
