       } %}
       {# we accumulate a joined name label and role label in  contributor_lod_accumulated_flat as a dedup check. Faster than
       iterating over every element we already build again on every new entry #}
       {% if (contributor.name_label ~ "-" ~ contributor.role_label) not in agents_lod_accumulated_flat %}
